import socket, time, sys, threading
# fake server: accept control connection, print what's received, send scripted replies
port = int(sys.argv[1]) if len(sys.argv)>1 else 7835
script = [eval(a) for a in sys.argv[2:]]
ls = socket.socket(); ls.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
ls.bind(("127.0.0.1", port)); ls.listen(5)
def handle(c, addr, n):
    c.settimeout(0.2)
    t0=time.time()
    i=0
    deadline=time.time()+6
    while time.time()<deadline:
        try:
            d=c.recv(4096)
            if not d: print(f"[{n}] closed by peer at {time.time()-t0:.3f}", flush=True); break
            print(f"[{n}] recv {d!r} at {time.time()-t0:.3f}", flush=True)
        except socket.timeout:
            pass
        except Exception as e:
            print(f"[{n}] exc {e} at {time.time()-t0:.3f}", flush=True); break
        if n==0:
            while i < len(script) and script[i][0] <= time.time()-t0:
                print(f"[{n}] send {script[i][1]!r} at {time.time()-t0:.3f}", flush=True)
                try: c.sendall(script[i][1])
                except Exception as e: print("send exc", e, flush=True)
                i+=1
    c.close()
n=0
ls.settimeout(8)
try:
    while True:
        c,addr=ls.accept()
        print(f"[{n}] accepted from {addr}", flush=True)
        threading.Thread(target=handle,args=(c,addr,n),daemon=True).start()
        n+=1
except socket.timeout:
    pass
