{"command":"cd /workspace && cat > src/log.rs <<'EOF'
//! Minimal structured logging facility.
//!
//! Produces output in the style of a typical "pretty" Rust tracing formatter:
//!
//! ```text
//! 2024-01-01T00:00:00.000000Z  INFO control{addr=1.2.3.4:5}: bore_cli::server: new client host=0.0.0.0 port=1234
//! ```
//!
//! Filtering is controlled by the `RUST_LOG` environment variable using the
//! familiar comma separated `target[{field,..}]=level` directive syntax.
//! Colored output is enabled unless the `NO_COLOR` environment variable is set
//! to a non-empty value.

use std::cell::RefCell;
use std::cmp::Ordering;
use std::fmt;
use std::io::Write;
use std::sync::OnceLock;
use std::time::{SystemTime, UNIX_EPOCH};

/// Severity of a log record, ordered from least to most verbose.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

impl Level {
    fn label(self) -> &'static str {
        match self {
            Level::Trace => "TRACE",
            Level::Debug => "DEBUG",
            Level::Info => " INFO",
            Level::Warn => " WARN",
            Level::Error => "ERROR",
        }
    }

    fn color(self) -> &'static str {
        match self {
            Level::Trace => "\x1b[35m",
            Level::Debug => "\x1b[34m",
            Level::Info => "\x1b[32m",
            Level::Warn => "\x1b[33m",
            Level::Error => "\x1b[31m",
        }
    }
}

/// A verbosity threshold. `None` means everything is disabled.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct LevelFilter(Option<Level>);

impl LevelFilter {
    const OFF: LevelFilter = LevelFilter(None);
    const ERROR: LevelFilter = LevelFilter(Some(Level::Error));
    const WARN: LevelFilter = LevelFilter(Some(Level::Warn));
    const INFO: LevelFilter = LevelFilter(Some(Level::Info));
    const DEBUG: LevelFilter = LevelFilter(Some(Level::Debug));
    const TRACE: LevelFilter = LevelFilter(Some(Level::Trace));

    fn allows(self, level: Level) -> bool {
        match self.0 {
            Some(max) => max >= level,
            None => false,
        }
    }

    fn parse(s: &str) -> Result<LevelFilter, ParseError> {
        if let Ok(num) = s.parse::<usize>() {
            return match num {
                0 => Ok(LevelFilter::OFF),
                1 => Ok(LevelFilter::ERROR),
                2 => Ok(LevelFilter::WARN),
                3 => Ok(LevelFilter::INFO),
                4 => Ok(LevelFilter::DEBUG),
                5 => Ok(LevelFilter::TRACE),
                _ => Err(ParseError::Level),
            };
        }
        match s {
            "" => Ok(LevelFilter::ERROR),
            s if s.eq_ignore_ascii_case("error") => Ok(LevelFilter::ERROR),
            s if s.eq_ignore_ascii_case("warn") => Ok(LevelFilter::WARN),
            s if s.eq_ignore_ascii_case("info") => Ok(LevelFilter::INFO),
            s if s.eq_ignore_ascii_case("debug") => Ok(LevelFilter::DEBUG),
            s if s.eq_ignore_ascii_case("trace") => Ok(LevelFilter::TRACE),
            s if s.eq_ignore_ascii_case("off") => Ok(LevelFilter::OFF),
            _ => Err(ParseError::Level),
        }
    }
}

/// Errors that can occur while parsing a filter string.
#[derive(Debug)]
enum ParseError {
    Level,
    Msg(&'static str),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Level => write!(
                f,
                "error parsing level filter: expected one of \"off\", \"error\", \
                 \"warn\", \"info\", \"debug\", \"trace\", or a number 0-5"
            ),
            ParseError::Msg(msg) => write!(f, "invalid filter directive: {msg}"),
        }
    }
}

/// A single filtering directive, e.g. `foo[{bar}]=info`.
#[derive(Debug, PartialEq, Eq)]
struct Directive {
    target: Option<String>,
    field_names: Vec<String>,
    level: LevelFilter,
}

impl Directive {
    fn parse(s: &str) -> Result<Directive, ParseError> {
        let mut split = s.split('=');
        let part0 = split.next().unwrap_or("");

        if let Some(part1) = split.next() {
            if split.next().is_some() {
                return Err(ParseError::Msg(
                    "too many '=' in filter directive, expected 0 or 1",
                ));
            }
            let mut split = part0.split("[{");
            let target = split.next().map(String::from);
            let mut field_names = Vec::new();
            if let Some(maybe_fields) = split.next() {
                if split.next().is_some() {
                    return Err(ParseError::Msg(
                        "too many '[{' in filter directive, expected 0 or 1",
                    ));
                }
                if !maybe_fields.ends_with("}]") {
                    return Err(ParseError::Msg("expected fields list to end with '}]'"));
                }
                field_names.extend(
                    maybe_fields
                        .trim_end_matches("}]")
                        .split(',')
                        .filter(|s| !s.is_empty())
                        .map(String::from),
                );
            }
            let level = LevelFilter::parse(part1)?;
            return Ok(Directive {
                target,
                field_names,
                level,
            });
        }

        Ok(match LevelFilter::parse(part0) {
            Ok(level) => Directive {
                target: None,
                field_names: Vec::new(),
                level,
            },
            Err(_) => Directive {
                target: Some(String::from(part0)),
                field_names: Vec::new(),
                level: LevelFilter::TRACE,
            },
        })
    }

    /// Specificity ordering: more specific directives sort first.
    fn specificity_cmp(&self, other: &Directive) -> Ordering {
        self.target
            .as_ref()
            .map(String::len)
            .cmp(&other.target.as_ref().map(String::len))
            .then_with(|| self.field_names.len().cmp(&other.field_names.len()))
            .then_with(|| self.field_names.cmp(&other.field_names))
            .then_with(|| self.target.cmp(&other.target))
            .reverse()
    }

    fn cares_about(&self, target: &str, fields: &[&str]) -> bool {
        if let Some(t) = &self.target {
            if !target.starts_with(t.as_str()) {
                return false;
            }
        }
        if !self.field_names.is_empty() {
            let has_all = self
                .field_names
                .iter()
                .all(|name| fields.iter().any(|f| f == name));
            if !has_all {
                return false;
            }
        }
        true
    }
}

/// An ordered set of directives.
#[derive(Debug, Default)]
struct Filter {
    directives: Vec<Directive>,
}

impl Filter {
    fn add(&mut self, directive: Directive) {
        match self
            .directives
            .binary_search_by(|d| d.specificity_cmp(&directive))
        {
            Ok(i) => self.directives[i] = directive,
            Err(i) => self.directives.insert(i, directive),
        }
    }

    fn parse(s: &str) -> Result<Filter, ParseError> {
        let mut filter = Filter::default();
        for part in s.split(',') {
            filter.add(Directive::parse(part)?);
        }
        Ok(filter)
    }

    fn with_default(level: LevelFilter) -> Filter {
        let mut filter = Filter::default();
        filter.add(Directive {
            target: None,
            field_names: Vec::new(),
            level,
        });
        filter
    }

    fn enabled(&self, level: Level, target: &str, fields: &[&str]) -> bool {
        match self
            .directives
            .iter()
            .find(|d| d.cares_about(target, fields))
        {
            Some(d) => d.level.allows(level),
            None => false,
        }
    }
}

struct Logger {
    filter: Filter,
    ansi: bool,
}

static LOGGER: OnceLock<Logger> = OnceLock::new();

fn logger() -> &'static Logger {
    LOGGER.get_or_init(|| Logger {
        filter: Filter::with_default(LevelFilter::INFO),
        ansi: true,
    })
}

/// Initialize the global logger from the environment.
pub fn init() {
    let filter = match std::env::var("RUST_LOG") {
        Ok(var) => match Filter::parse(&var) {
            Ok(filter) => filter,
            Err(err) => {
                eprintln!("Ignoring `RUST_LOG={var:?}`: {err}");
                Filter::default()
            }
        },
        Err(std::env::VarError::NotPresent) => Filter::with_default(LevelFilter::INFO),
        Err(err) => {
            eprintln!("Ignoring `RUST_LOG`: {err}");
            Filter::with_default(LevelFilter::INFO)
        }
    };
    let ansi = std::env::var("NO_COLOR").map_or(true, |v| v.is_empty());
    let _ = LOGGER.set(Logger { filter, ansi });
}

/// Returns whether a record with the given metadata would be emitted.
pub fn enabled(level: Level, target: &str, fields: &[&str]) -> bool {
    logger().filter.enabled(level, target, fields)
}

/// A span of execution, rendered as a prefix for records emitted inside it.
#[derive(Debug, Clone)]
pub struct Span {
    name: &'static str,
    fields: Vec<(&'static str, String)>,
    enabled: bool,
}

impl Span {
    pub fn new(
        level: Level,
        target: &str,
        name: &'static str,
        fields: Vec<(&'static str, String)>,
    ) -> Span {
        let names: Vec<&str> = fields.iter().map(|(n, _)| *n).collect();
        let enabled = enabled(level, target, &names);
        Span {
            name,
            fields,
            enabled,
        }
    }

    /// Enters the span on the current thread until the returned guard drops.
    pub fn enter(&self) -> SpanGuard {
        SPANS.with(|spans| spans.borrow_mut().push(self.clone()));
        SpanGuard { _priv: () }
    }

    fn render(&self, out: &mut String, ansi: bool) {
        if !self.enabled {
            return;
        }
        if ansi {
            out.push_str("\x1b[1m");
            out.push_str(self.name);
            out.push_str("\x1b[0m");
            if !self.fields.is_empty() {
                out.push_str("\x1b[1m{\x1b[0m");
                for (i, (name, value)) in self.fields.iter().enumerate() {
                    if i > 0 {
                        out.push(' ');
                    }
                    out.push_str("\x1b[3m");
                    out.push_str(name);
                    out.push_str("\x1b[0m\x1b[2m=\x1b[0m");
                    out.push_str(value);
                }
                out.push_str("\x1b[1m}\x1b[0m");
            }
            out.push_str("\x1b[2m:\x1b[0m ");
        } else {
            out.push_str(self.name);
            if !self.fields.is_empty() {
                out.push('{');
                for (i, (name, value)) in self.fields.iter().enumerate() {
                    if i > 0 {
                        out.push(' ');
                    }
                    out.push_str(name);
                    out.push('=');
                    out.push_str(value);
                }
                out.push('}');
            }
            out.push_str(": ");
        }
    }
}

pub struct SpanGuard {
    _priv: (),
}

impl Drop for SpanGuard {
    fn drop(&mut self) {
        SPANS.with(|spans| {
            spans.borrow_mut().pop();
        });
    }
}

thread_local! {
    static SPANS: RefCell<Vec<Span>> = const { RefCell::new(Vec::new()) };
}

/// Formats the current time as an RFC 3339 timestamp with microseconds.
fn timestamp(out: &mut String) {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = now.as_secs() as i64;
    let micros = now.subsec_micros();

    let days = secs.div_euclid(86_400);
    let rem = secs.rem_euclid(86_400);
    let (hour, minute, second) = (rem / 3600, (rem % 3600) / 60, rem % 60);

    // Civil-from-days algorithm (Howard Hinnant).
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };

    use std::fmt::Write as _;
    let _ = write!(
        out,
        "{y:04}-{m:02}-{d:02}T{hour:02}:{minute:02}:{second:02}.{micros:06}Z"
    );
}

/// Emits a record. `fields` are rendered as `name=value` pairs after the message.
pub fn log(level: Level, target: &str, message: &str, fields: &[(&str, String)]) {
    let lg = logger();
    let mut names: Vec<&str> = Vec::with_capacity(fields.len() + 1);
    if !message.is_empty() {
        names.push("message");
    }
    names.extend(fields.iter().map(|(n, _)| *n));
    if !lg.filter.enabled(level, target, &names) {
        return;
    }

    let mut line = String::with_capacity(128);
    if lg.ansi {
        line.push_str("\x1b[2m");
        timestamp(&mut line);
        line.push_str("\x1b[0m ");
        line.push_str(level.color());
        line.push_str(level.label());
        line.push_str("\x1b[0m ");
    } else {
        timestamp(&mut line);
        line.push(' ');
        line.push_str(level.label());
        line.push(' ');
    }

    SPANS.with(|spans| {
        for span in spans.borrow().iter() {
            span.render(&mut line, lg.ansi);
        }
    });

    if lg.ansi {
        line.push_str("\x1b[2m");
        line.push_str(target);
        line.push_str("\x1b[0m\x1b[2m:\x1b[0m ");
    } else {
        line.push_str(target);
        line.push_str(": ");
    }

    line.push_str(message);
    for (i, (name, value)) in fields.iter().enumerate() {
        if i > 0 || !message.is_empty() {
            line.push(' ');
