            line.push_str(name);
            line.push_str("\x1b[0m\x1b[2m=\x1b[0m");
        } else {
            line.push_str(name);
            line.push('=');
        }
        line.push_str(value);
    }
    line.push('\n');

    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(line.as_bytes());
    let _ = handle.flush();
}

