use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::trace;

/// TCP port used for control connections with the server.
pub const CONTROL_PORT: u16 = 7835;

/// Maximum byte length for a JSON frame in the stream.
pub const MAX_FRAME_LENGTH: usize = 256;

/// Timeout for network connections and initial protocol messages.
pub const NETWORK_TIMEOUT: Duration = Duration::from_secs(3);

const TARGET: &str = "bore_cli::shared";

/// A message from the client on the control connection.
#[derive(Debug, Serialize, Deserialize)]
pub enum ClientMessage {
    /// Response to an authentication challenge from the server.
    Authenticate(String),

    /// Initial client message specifying a port to forward.
    Hello(u16),

    /// Accepts an incoming TCP connection, using this stream as a proxy.
    Accept(Uuid),
}

/// A message from the server on the control connection.
#[derive(Debug, Serialize, Deserialize)]
pub enum ServerMessage {
    /// Authentication challenge, sent as the first message, if enabled.
    Challenge(Uuid),

    /// Response to a client's initial message, with actual public port.
    Hello(u16),

    /// No-op used to test if the client is still reachable.
    Heartbeat,

    /// Asks the client to accept a forwarded TCP connection.
    Connection(Uuid),

    /// Indicates a server error that terminates the connection.
    Error(String),
}

/// Error returned when an operation does not complete within its deadline.
#[derive(Debug)]
pub struct Elapsed(());

impl std::fmt::Display for Elapsed {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("deadline has elapsed")
    }
}

impl std::error::Error for Elapsed {}

/// Error returned when a frame exceeds the maximum permitted length.
#[derive(Debug)]
pub struct MaxChunkLengthExceeded;

impl std::fmt::Display for MaxChunkLengthExceeded {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("max chunk length exceeded")
    }
}

impl std::error::Error for MaxChunkLengthExceeded {}

/// The raw pieces of a [`Delimited`] stream, obtained after framing is no
/// longer needed.
pub struct Parts {
    /// The underlying stream.
    pub io: TcpStream,
    /// Bytes that were read from the stream but not yet consumed as a frame.
    pub read_buf: Vec<u8>,
}

/// Transport layer that sends and receives null-delimited JSON messages.
pub struct Delimited {
    stream: TcpStream,
    buf: Vec<u8>,
    eof: bool,
}

impl Delimited {
    /// Construct a new delimited stream.
    pub fn new(stream: TcpStream) -> Self {
        Delimited {
            stream,
            buf: Vec::with_capacity(1024),
            eof: false,
        }
    }

    /// Read the next null-delimited JSON instruction from a stream.
    pub fn recv<T: DeserializeOwned>(&mut self) -> Result<Option<T>> {
        trace!(TARGET, "waiting to receive json message");
        let _ = self.stream.set_read_timeout(None);
        match self.next_frame(None)? {
            Some(frame) => {
                let msg = serde_json::from_slice(&frame).context("unable to parse message")?;
                Ok(Some(msg))
            }
            None => Ok(None),
        }
    }

    /// Read the next null-delimited JSON instruction, with a default timeout.
    ///
    /// This is useful for parsing the initial message of a stream for handshake or
    /// other protocol purposes, where we do not want to wait indefinitely.
    pub fn recv_timeout<T: DeserializeOwned>(&mut self) -> Result<Option<T>> {
        trace!(TARGET, "waiting to receive json message");
        let deadline = Instant::now() + NETWORK_TIMEOUT;
        let result = self.next_frame(Some(deadline));
        let _ = self.stream.set_read_timeout(None);
        match result.context("timed out waiting for initial message")? {
            Some(frame) => {
                let msg = serde_json::from_slice(&frame).context("unable to parse message")?;
                Ok(Some(msg))
