/// Connects to a host and port, with a default network timeout.
///
/// Name resolution and the connection attempt happen on a helper thread so
/// that the whole operation can be bounded by [`NETWORK_TIMEOUT`].
pub fn connect_with_timeout(to: &str, port: u16) -> Result<TcpStream> {
    let host = to.to_string();
    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        let result = (|| -> io::Result<TcpStream> {
            let addrs = (host.as_str(), port).to_socket_addrs()?;
