/// Copies data in one direction, propagating end-of-stream as a write shutdown.
fn copy_one_direction(mut reader: &TcpStream, mut writer: &TcpStream) -> io::Result<()> {
    let mut buf = [0u8; 16 * 1024];
    loop {
        let n = match reader.read(&mut buf) {
            Ok(n) => n,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        };
        if n == 0 {
            writer.shutdown(Shutdown::Write)?;
