///
/// When one direction fails, the other is aborted and the first error is
/// returned.
pub fn proxy(a: TcpStream, b: TcpStream) -> io::Result<()> {
    let _ = a.set_read_timeout(None);
    let _ = b.set_read_timeout(None);
    let a2 = a.try_clone()?;
    let b2 = b.try_clone()?;

    let first_error: Arc<Mutex<Option<io::Error>>> = Arc::new(Mutex::new(None));

    let record = |err: io::Error, x: &TcpStream, y: &TcpStream| {
        let mut slot = first_error.lock().unwrap_or_else(|e| e.into_inner());
        if slot.is_none() {
            *slot = Some(err);
            // Abort the other direction.
            let _ = x.shutdown(Shutdown::Both);
            let _ = y.shutdown(Shutdown::Both);
        }
    };

    let handle = {
        let first_error = Arc::clone(&first_error);
        thread::spawn(move || {
            if let Err(err) = copy_one_direction(&a2, &b2) {
                let mut slot = first_error.lock().unwrap_or_else(|e| e.into_inner());
                if slot.is_none() {
                    *slot = Some(err);
                    let _ = a2.shutdown(Shutdown::Both);
                    let _ = b2.shutdown(Shutdown::Both);
                }
            }
        })
    };

    if let Err(err) = copy_one_direction(&b, &a) {
        record(err, &a, &b);
    }
    let _ = handle.join();

    let mut slot = first_error.lock().unwrap_or_else(|e| e.into_inner());
    match slot.take() {
        Some(err) => Err(err),
        None => Ok(()),
    }
}
