//! Authentication handshake using a shared secret.
//!
//! The server issues a random challenge; the client proves knowledge of the
//! secret by returning an HMAC-SHA256 tag over the challenge bytes, keyed by
//! the SHA-256 digest of the secret.

use anyhow::{bail, ensure, Result};
use sha2::{Digest, Sha256};
use uuid::Uuid;

use crate::shared::{ClientMessage, Delimited, ServerMessage};

const BLOCK_SIZE: usize = 64;

/// Wrapper around a secret key that performs the authentication handshake.
pub struct Authenticator {
    key: [u8; 32],
}

/// Computes HMAC-SHA256 of `message` under `key`.
fn hmac_sha256(key: &[u8], message: &[u8]) -> [u8; 32] {
    let mut key_block = [0u8; BLOCK_SIZE];
    if key.len() > BLOCK_SIZE {
        let digest = Sha256::digest(key);
        key_block[..32].copy_from_slice(&digest);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    let mut ipad = [0u8; BLOCK_SIZE];
    let mut opad = [0u8; BLOCK_SIZE];
    for i in 0..BLOCK_SIZE {
        ipad[i] = key_block[i] ^ 0x36;
        opad[i] = key_block[i] ^ 0x5c;
    }

    let mut inner = Sha256::new();
    inner.update(ipad);
    inner.update(message);
    let inner_digest = inner.finalize();

    let mut outer = Sha256::new();
    outer.update(opad);
    outer.update(inner_digest);
    outer.finalize().into()
}

/// Constant-time comparison of two byte slices.
fn ct_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

impl Authenticator {
    /// Generate an authenticator from a secret.
    pub fn new(secret: &str) -> Self {
        let key: [u8; 32] = Sha256::digest(secret.as_bytes()).into();
        Authenticator { key }
    }

    /// Generate a reply message for a challenge.
    pub fn answer(&self, challenge: &Uuid) -> String {
        hex::encode(hmac_sha256(&self.key, challenge.as_bytes()))
    }

    /// Validate a reply to a challenge.
    pub fn validate(&self, challenge: &Uuid, tag: &str) -> bool {
        match hex::decode(tag) {
            Ok(decoded) => ct_eq(&decoded, &hmac_sha256(&self.key, challenge.as_bytes())),
            Err(_) => false,
        }
    }

    /// As the server, send a challenge and verify the client's response.
    pub fn server_handshake(&self, stream: &mut Delimited) -> Result<()> {
        let challenge = Uuid::new_v4();
        stream.send(ServerMessage::Challenge(challenge))?;
        match stream.recv_timeout()? {
            Some(ClientMessage::Authenticate(tag)) => {
                ensure!(self.validate(&challenge, &tag), "invalid secret");
                Ok(())
            }
            _ => bail!("server requires secret, but no secret was provided"),
        }
    }

    /// As the client, answer a challenge to attempt to authenticate.
    pub fn client_handshake(&self, stream: &mut Delimited) -> Result<()> {
        let challenge = match stream.recv_timeout()? {
            Some(ServerMessage::Challenge(challenge)) => challenge,
            _ => bail!("expected authentication challenge, but no secret was required"),
        };
        let tag = self.answer(&challenge);
        stream.send(ClientMessage::Authenticate(tag))?;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_answer() {
        let auth = Authenticator::new("abc");
        let challenge = Uuid::parse_str("11111111-2222-3333-4444-555555555555").unwrap();
        assert_eq!(
            auth.answer(&challenge),
            "29eebfb152ebf802e789e065a6c1e218cce1567d54dc6557eb710e98c9cc28c8"
        );
        assert!(auth.validate(
            &challenge,
            "29eebfb152ebf802e789e065a6c1e218cce1567d54dc6557eb710e98c9cc28c8"
        ));
        assert!(!auth.validate(&challenge, "zz"));
    }
}
