//! Server implementation for the `bore` service.

use std::collections::HashMap;
use std::io::{self, Write};
use std::net::{IpAddr, SocketAddr, TcpListener, TcpStream};
use std::ops::RangeInclusive;
use std::os::unix::io::AsRawFd;
use std::sync::{mpsc, Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

use anyhow::Result;
use rand::Rng;
use uuid::Uuid;

use crate::auth::Authenticator;
use crate::log::{Level, Span};
use crate::shared::{proxy, ClientMessage, Delimited, ServerMessage, CONTROL_PORT};
use crate::{info, warn};

const TARGET: &str = "bore_cli::server";

/// How long a forwarded connection may wait for the client to accept it.
const STALE_CONNECTION_TIMEOUT: Duration = Duration::from_secs(10);

/// Interval between heartbeat messages on the control connection.
const HEARTBEAT_INTERVAL: Duration = Duration::from_millis(500);

type Connections = Arc<Mutex<HashMap<Uuid, TcpStream>>>;

/// State structure for the server.
pub struct Server {
    /// Range of TCP ports that can be forwarded.
    port_range: RangeInclusive<u16>,

    /// Optional secret used to authenticate clients.
    auth: Option<Authenticator>,

    /// Concurrent map of IDs to incoming connections.
    conns: Connections,

    /// IP address where the control server will bind to.
    bind_addr: IpAddr,

    /// IP address where tunnels will listen on.
    bind_tunnels: IpAddr,

    /// Queue of connections awaiting stale-entry cleanup.
    reaper: Mutex<Option<mpsc::Sender<(Instant, Uuid)>>>,
}

impl Server {
    /// Create a new server with a specified minimum port number.
    pub fn new(port_range: RangeInclusive<u16>, secret: Option<&str>) -> Self {
        assert!(!port_range.is_empty(), "must provide at least one port");
        Server {
            port_range,
            conns: Arc::new(Mutex::new(HashMap::new())),
            auth: secret.map(Authenticator::new),
            bind_addr: "0.0.0.0".parse().unwrap(),
            bind_tunnels: "0.0.0.0".parse().unwrap(),
            reaper: Mutex::new(None),
        }
    }

    /// Set the IP address where tunnels will listen on.
    pub fn set_bind_addr(&mut self, bind_addr: IpAddr) {
        self.bind_addr = bind_addr;
    }

    /// Set the IP address where tunnels will listen on.
    pub fn set_bind_tunnels(&mut self, bind_tunnels: IpAddr) {
        self.bind_tunnels = bind_tunnels;
    }

    /// Start the server, listening for new connections.
    pub fn listen(self) -> Result<()> {
        let this = Arc::new(self);
        this.start_reaper();
        let addr = SocketAddr::new(this.bind_addr, CONTROL_PORT);
        let listener = TcpListener::bind(addr)?;
        info!(TARGET, "server listening", addr = this.bind_addr);

        loop {
            let (stream, addr) = match listener.accept() {
                Ok(accepted) => accepted,
                Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(e.into()),
            };
            let this = Arc::clone(&this);
            thread::spawn(move || {
                let span = Span::new(
                    Level::Info,
                    TARGET,
                    "control",
                    vec![("addr", addr.to_string())],
                );
                let _guard = span.enter();
                info!(TARGET, "incoming connection");
                match this.handle_connection(stream) {
                    Ok(()) => info!(TARGET, "connection exited"),
                    Err(err) => warn!(TARGET, "connection exited with error", err = err),
                }
            });
        }
    }

    /// Spawns the background thread that removes stale pending connections.
    fn start_reaper(&self) {
        let (tx, rx) = mpsc::channel::<(Instant, Uuid)>();
        *self.reaper.lock().unwrap_or_else(|e| e.into_inner()) = Some(tx);
        let conns = Arc::clone(&self.conns);
        thread::spawn(move || {
            while let Ok((deadline, id)) = rx.recv() {
                let now = Instant::now();
                if deadline > now {
                    thread::sleep(deadline - now);
                }
                let removed = conns
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&id)
                    .is_some();
                if removed {
                    warn!(TARGET, "removed stale connection", id = id);
                }
            }
        });
    }

    fn schedule_reap(&self, id: Uuid) {
        let deadline = Instant::now() + STALE_CONNECTION_TIMEOUT;
        if let Some(tx) = self.reaper.lock().unwrap_or_else(|e| e.into_inner()).as_ref() {
            let _ = tx.send((deadline, id));
        }
    }

    fn create_listener(&self, port: u16) -> Result<TcpListener, &'static str> {
        let try_bind = |port: u16| -> io::Result<TcpListener> {
            TcpListener::bind(SocketAddr::new(self.bind_tunnels, port))
        };
        if port > 0 {
            // Client requests a specific port number.
            if !self.port_range.contains(&port) {
                return Err("client port number not in allowed range");
            }
            try_bind(port).map_err(|_| "port already in use")
        } else {
            // Client requests any available port in range.
            //
            // In this case, we bind to 150 random port numbers. We choose this
            // over binding to port 0 and relying on the OS to allocate a port
            // because we want to limit the range to the user's configuration.
            let mut rng = rand::thread_rng();
            for _ in 0..150 {
                let port = rng.gen_range(self.port_range.clone());
                match try_bind(port) {
                    Ok(listener) => return Ok(listener),
                    Err(_) => continue,
                }
            }
            Err("failed to find an available port")
        }
    }

    fn handle_connection(&self, stream: TcpStream) -> Result<()> {
        let mut stream = Delimited::new(stream);
        if let Some(auth) = &self.auth {
            if let Err(err) = auth.server_handshake(&mut stream) {
                warn!(TARGET, "server handshake failed", err = err);
                stream.send(ServerMessage::Error(err.to_string()))?;
                return Ok(());
            }
        }

        match stream.recv_timeout()? {
            Some(ClientMessage::Authenticate(_)) => {
                warn!(TARGET, "unexpected authenticate");
                Ok(())
            }
            Some(ClientMessage::Hello(port)) => {
                let listener = match self.create_listener(port) {
                    Ok(listener) => listener,
                    Err(err) => {
                        stream.send(ServerMessage::Error(err.into()))?;
                        return Ok(());
                    }
                };
                let host = self.bind_tunnels;
                let port = listener.local_addr()?.port();
                info!(TARGET, "new client", host = host, port = port);
                stream.send(ServerMessage::Hello(port))?;
                listener.set_nonblocking(true)?;

                loop {
                    if stream.send(ServerMessage::Heartbeat).is_err() {
                        // Assume that the TCP connection has been dropped.
                        return Ok(());
                    }
                    if let Some((stream2, addr)) = accept_timeout(&listener, HEARTBEAT_INTERVAL)? {
                        let _ = stream2.set_nonblocking(false);
                        info!(TARGET, "new connection", addr = addr, port = port);

                        let id = Uuid::new_v4();
                        self.conns
                            .lock()
                            .unwrap_or_else(|e| e.into_inner())
                            .insert(id, stream2);
                        // Remove stale entries to avoid memory leaks.
                        self.schedule_reap(id);
                        stream.send(ServerMessage::Connection(id))?;
                    }
                }
            }
            Some(ClientMessage::Accept(id)) => {
                info!(TARGET, "forwarding connection", id = id);
                let stream2 = self
                    .conns
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&id);
                match stream2 {
                    Some(mut stream2) => {
                        let parts = stream.into_parts();
                        if !parts.read_buf.is_empty() {
                            stream2.write_all(&parts.read_buf)?;
                        }
                        proxy(parts.io, stream2)?;
                    }
                    None => warn!(TARGET, "missing connection", id = id),
                }
                Ok(())
            }
            None => Ok(()),
        }
    }
}

/// Waits up to `timeout` for an incoming connection on a non-blocking listener.
fn accept_timeout(
    listener: &TcpListener,
    timeout: Duration,
) -> io::Result<Option<(TcpStream, SocketAddr)>> {
    let deadline = Instant::now() + timeout;
    loop {
        let now = Instant::now();
        if now >= deadline {
            return Ok(None);
        }
        let remaining = deadline - now;
        let millis = remaining.as_millis().min(i32::MAX as u128) as i32;
        let millis = if remaining.subsec_nanos() % 1_000_000 != 0 {
            millis.saturating_add(1)
        } else {
            millis
        };
        let mut pfd = libc::pollfd {
            fd: listener.as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        let ret = unsafe { libc::poll(&mut pfd, 1, millis) };
        if ret < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }
        if ret == 0 {
            return Ok(None);
        }
        match listener.accept() {
            Ok(accepted) => return Ok(Some(accepted)),
            Err(e)
                if matches!(
                    e.kind(),
                    io::ErrorKind::WouldBlock | io::ErrorKind::Interrupted
                ) =>
            {
                continue;
            }
            Err(e) => return Err(e),
        }
    }
}
