        match stream.recv_timeout()? {
            Some(ClientMessage::Authenticate(_)) => {
                warn!(TARGET, "unexpected authenticate");
                Ok(())
            }
            Some(ClientMessage::Hello(port)) => {
                let listener = match self.create_listener(port) {
                    Ok(listener) => listener,
                    Err(err) => {
                        stream.send(ServerMessage::Error(err.into()))?;
                        return Ok(());
                    }
                };
                let host = self.bind_tunnels;
                let port = listener.local_addr()?.port();
                info!(TARGET, "new client", host = host, port = port);
                stream.send(ServerMessage::Hello(port))?;
                listener.set_nonblocking(true)?;

                loop {
                    if stream.send(ServerMessage::Heartbeat).is_err() {
                        // Assume that the TCP connection has been dropped.
                        return Ok(());
                    }
                    if let Some((stream2, addr)) = accept_timeout(&listener, HEARTBEAT_INTERVAL)? {
                        let _ = stream2.set_nonblocking(false);
                        info!(TARGET, "new connection", addr = addr, port = port);

                        let id = Uuid::new_v4();
                        self.conns
                            .lock()
                            .unwrap_or_else(|e| e.into_inner())
                            .insert(id, stream2);
                        // Remove stale entries to avoid memory leaks.
                        self.schedule_reap(id);
                        stream.send(ServerMessage::Connection(id))?;
                    }
                }
            }
            Some(ClientMessage::Accept(id)) => {
                info!(TARGET, "forwarding connection", id = id);
                let stream2 = self
                    .conns
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&id);
                match stream2 {
                    Some(mut stream2) => {
                        let parts = stream.into_parts();
                        if !parts.read_buf.is_empty() {
                            stream2.write_all(&parts.read_buf)?;
                        }
                        proxy(parts.io, stream2)?;
                    }
                    None => warn!(TARGET, "missing connection", id = id),
                }
                Ok(())
            }
            None => Ok(()),
        }
    }
}

/// Waits up to `timeout` for an incoming connection on a non-blocking listener.
fn accept_timeout(
    listener: &TcpListener,
    timeout: Duration,
) -> io::Result<Option<(TcpStream, SocketAddr)>> {
    let deadline = Instant::now() + timeout;
    loop {
        let now = Instant::now();
        if now >= deadline {
            return Ok(None);
        }
        let remaining = deadline - now;
        let millis = remaining.as_millis().min(i32::MAX as u128) as i32;
        let millis = if remaining.subsec_nanos() % 1_000_000 != 0 {
            millis.saturating_add(1)
        } else {
            millis
        };
        let mut pfd = libc::pollfd {
            fd: listener.as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        let ret = unsafe { libc::poll(&mut pfd, 1, millis) };
        if ret < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }
        if ret == 0 {
            return Ok(None);
        }
        match listener.accept() {
            Ok(accepted) => return Ok(Some(accepted)),
            Err(e)
                if matches!(
                    e.kind(),
                    io::ErrorKind::WouldBlock | io::ErrorKind::Interrupted
                ) =>
            {
                continue;
            }
            Err(e) => return Err(e),
        }
    }
}
