/// A universally unique identifier.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Uuid([u8; 16]);

/// Error produced when a string cannot be parsed as a UUID.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    /// A character that is neither hex nor a hyphen was found.
    Char { character: char, index: usize },
    /// A non-hyphenated UUID did not contain 32 characters.
    SimpleLength { len: usize },
    /// A hyphenated UUID did not contain 5 groups.
    GroupCount { count: usize },
    /// A hyphenated UUID had a group of the wrong length.
    GroupLength { group: usize, len: usize },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            ParseError::Char { character, index } => write!(
                f,
                "invalid character: expected an optional prefix of `urn:uuid:` followed by \
                 [0-9a-fA-F-], found `{character}` at {index}"
            ),
            ParseError::SimpleLength { len } => write!(
                f,
                "invalid length: expected length 32 for simple format, found {len}"
            ),
            ParseError::GroupCount { count } => {
                write!(f, "invalid group count: expected 5, found {count}")
            }
            ParseError::GroupLength { group, len } => {
                let expected = [8, 4, 4, 4, 12][group];
                write!(
                    f,
                    "invalid group length in group {group}: expected {expected}, found {len}"
                )
            }
        }
    }
}

impl std::error::Error for ParseError {}

const HEX_LOWER: &[u8; 16] = b"0123456789abcdef";

fn hex_value(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

/// Parses 32 hex digits without separators.
fn parse_simple(s: &[u8]) -> Option<[u8; 16]> {
    if s.len() != 32 {
        return None;
    }
    let mut out = [0u8; 16];
    for (i, chunk) in s.chunks(2).enumerate() {
        out[i] = (hex_value(chunk[0])? << 4) | hex_value(chunk[1])?;
    }
    Some(out)
}

/// Parses the `8-4-4-4-12` hyphenated layout.
fn parse_hyphenated(s: &[u8]) -> Option<[u8; 16]> {
    if s.len() != 36 {
        return None;
    }
    if s[8] != b'-' || s[13] != b'-' || s[18] != b'-' || s[23] != b'-' {
        return None;
    }
    let mut digits = Vec::with_capacity(32);
    for (i, &b) in s.iter().enumerate() {
        if matches!(i, 8 | 13 | 18 | 23) {
            continue;
        }
        digits.push(b);
    }
    parse_simple(&digits)
}

impl Uuid {
    /// The nil UUID (all zeros).
    pub const fn nil() -> Uuid {
        Uuid([0; 16])
    }

    /// Creates a UUID from raw bytes.
    pub const fn from_bytes(bytes: [u8; 16]) -> Uuid {
        Uuid(bytes)
    }

    /// Generates a random (version 4) UUID.
    pub fn new_v4() -> Uuid {
        let mut bytes = [0u8; 16];
        rand::thread_rng().fill_bytes(&mut bytes);
        bytes[6] = (bytes[6] & 0x0f) | 0x40; // version 4
        bytes[8] = (bytes[8] & 0x3f) | 0x80; // RFC 4122 variant
        Uuid(bytes)
    }

    /// Returns the raw bytes of the UUID.
    pub fn as_bytes(&self) -> &[u8; 16] {
        &self.0
    }

    /// Parses a UUID from any of the supported textual forms: simple,
    /// hyphenated, braced (`{...}`) or URN (`urn:uuid:...`).
    pub fn parse_str(input: &str) -> Result<Uuid, ParseError> {
        let bytes = input.as_bytes();
        let parsed = match bytes.len() {
            32 => parse_simple(bytes),
            36 => parse_hyphenated(bytes),
            38 if bytes[0] == b'{' && bytes[37] == b'}' => parse_hyphenated(&bytes[1..37]),
            45 if bytes.starts_with(b"urn:uuid:") => parse_hyphenated(&bytes[9..]),
            _ => None,
        };
        match parsed {
            Some(b) => Ok(Uuid(b)),
            None => Err(diagnose(input)),
        }
    }
}

/// Produces a detailed error for an input that failed to parse.
fn diagnose(input: &str) -> ParseError {
    let bytes = input.as_bytes();
    let (body, offset, simple) = if bytes.len() >= 2 && bytes[0] == b'{' && bytes[bytes.len() - 1] == b'}'
    {
        (&input[1..input.len() - 1], 1usize, false)
    } else if let Some(rest) = input.strip_prefix("urn:uuid:") {
        (rest, "urn:uuid:".len(), false)
    } else {
        (input, 0usize, true)
    };

    let mut hyphen_count = 0usize;
    let mut group_bounds = [0usize; 4];
    for (index, character) in body.char_indices() {
        if !character.is_ascii() {
            return ParseError::Char {
                character,
                index: index + offset + 1,
            };
        }
        let byte = character as u8;
        if byte == b'-' {
            if hyphen_count < 4 {
                group_bounds[hyphen_count] = index;
            }
            hyphen_count += 1;
        } else if hex_value(byte).is_none() {
            return ParseError::Char {
                character,
                index: index + offset + 1,
            };
        }
    }

    if hyphen_count == 0 && simple {
        ParseError::SimpleLength { len: input.len() }
    } else if hyphen_count != 4 {
        ParseError::GroupCount {
            count: hyphen_count + 1,
        }
    } else {
        const BLOCK_STARTS: [usize; 5] = [0, 9, 14, 19, 24];
        for i in 0..4 {
            if group_bounds[i] != BLOCK_STARTS[i + 1] - 1 {
                return ParseError::GroupLength {
                    group: i,
                    len: group_bounds[i].wrapping_sub(BLOCK_STARTS[i]),
                };
            }
        }
        ParseError::GroupLength {
            group: 4,
            len: input.len() - BLOCK_STARTS[4],
        }
    }
}

impl FromStr for Uuid {
    type Err = ParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Uuid::parse_str(s)
    }
}

impl fmt::Display for Uuid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut buf = [0u8; 36];
        let mut pos = 0;
        for (i, byte) in self.0.iter().enumerate() {
            if matches!(i, 4 | 6 | 8 | 10) {
                buf[pos] = b'-';
                pos += 1;
            }
            buf[pos] = HEX_LOWER[(byte >> 4) as usize];
            buf[pos + 1] = HEX_LOWER[(byte & 0x0f) as usize];
            pos += 2;
        }
        // SAFETY-free: buffer only contains ASCII characters.
        f.write_str(std::str::from_utf8(&buf).expect("ascii"))
    }
}

impl fmt::Debug for Uuid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(self, f)
    }
}

impl Serialize for Uuid {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.collect_str(self)
    }
}

struct UuidVisitor;

impl<'de> Visitor<'de> for UuidVisitor {
    type Value = Uuid;

    fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("a UUID string")
    }

    fn visit_str<E: de::Error>(self, value: &str) -> Result<Uuid, E> {
        Uuid::parse_str(value)
            .map_err(|err| E::custom(format_args!("UUID parsing failed: {err}")))
    }

    fn visit_bytes<E: de::Error>(self, value: &[u8]) -> Result<Uuid, E> {
        match std::str::from_utf8(value) {
            Ok(s) => self.visit_str(s),
            Err(_) => Err(E::custom("UUID parsing failed: non-UTF8 input")),
        }
    }
}

impl<'de> Deserialize<'de> for Uuid {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Uuid, D::Error> {
        deserializer.deserialize_str(UuidVisitor)
    }
}

#[cfg(test)]
mod tests {
