    #[test]
    fn roundtrip() {
        let id = Uuid::new_v4();
        let text = id.to_string();
        assert_eq!(text.len(), 36);
        assert_eq!(Uuid::parse_str(&text).unwrap(), id);
        assert_eq!(text.as_bytes()[14], b'4');
    }

    #[test]
    fn formats() {
        let id = Uuid::parse_str("11111111-2222-3333-4444-555555555555").unwrap();
        assert_eq!(Uuid::parse_str("11111111222233334444555555555555").unwrap(), id);
        assert_eq!(Uuid::parse_str("{11111111-2222-3333-4444-555555555555}").unwrap(), id);
        assert_eq!(
