    }

    #[test]
    fn errors() {
        let e = |s: &str| Uuid::parse_str(s).unwrap_err().to_string();
        assert_eq!(e("not-a-uuid"), "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `n` at 1");
