        assert_eq!(e("1111111-22222-3333-4444-555555555555"), "invalid group length in group 0: expected 8, found 7");
        assert_eq!(e("11111111-2222-3333-44444-55555555555"), "invalid group length in group 3: expected 4, found 5");
        assert_eq!(e("{11111111-2222-3333-4444-55555555555}"), "invalid group length in group 4: expected 12, found 13");
        assert_eq!(e("urn:uuid:11111111-2222-3333-4444-55555555555"), "invalid group length in group 4: expected 12, found 20");
        assert_eq!(e("{not-a-uuid}"), "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `n` at 2");
        assert_eq!(e("urn:uuid:zz"), "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `z` at 10");
        assert_eq!(e("{abc}"), "invalid group count: expected 5, found 1");
        assert_eq!(e("11111111-2222-3333-4444-555555555555-"), "invalid group count: expected 5, found 6");
        assert_eq!(e("{1111-2222-3333-4444-5555}"), "invalid group length in group 0: expected 8, found 4");
        assert_eq!(e("é"), "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `é` at 1");
        assert_eq!(e("11111111-2222-3333-4444-5555555555é5"), "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `é` at 35");
        assert_eq!(e("{{11111111-2222-3333-4444-555555555555}}"), "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `{` at 2");
    }
}
