/// Produces a detailed error for an input that failed to parse.
fn diagnose(input: &str) -> ParseError {
    let bytes = input.as_bytes();
    let (body, offset, simple) = if bytes.len() >= 2 && bytes[0] == b'{' && bytes[bytes.len() - 1] == b'}'
    {
        (&input[1..input.len() - 1], 1usize, false)
    } else if let Some(rest) = input.strip_prefix("urn:uuid:") {
        (rest, "urn:uuid:".len(), false)
    } else {
        (input, 0usize, true)
    };

    let mut hyphen_count = 0usize;
    let mut group_bounds = [0usize; 4];
    for (index, character) in body.char_indices() {
        if !character.is_ascii() {
            return ParseError::Char {
                character,
                index: index + offset + 1,
            };
        }
        let byte = character as u8;
        if byte == b'-' {
            if hyphen_count < 4 {
                group_bounds[hyphen_count] = index;
            }
            hyphen_count += 1;
        } else if hex_value(byte).is_none() {
            return ParseError::Char {
                character,
                index: index + offset + 1,
            };
        }
    }

    if hyphen_count == 0 && simple {
        ParseError::SimpleLength { len: input.len() }
    } else if hyphen_count != 4 {
        ParseError::GroupCount {
            count: hyphen_count + 1,
        }
    } else {
        const BLOCK_STARTS: [usize; 5] = [0, 9, 14, 19, 24];
        for i in 0..4 {
            if group_bounds[i] != BLOCK_STARTS[i + 1] - 1 {
                return ParseError::GroupLength {
                    group: i,
                    len: group_bounds[i].wrapping_sub(BLOCK_STARTS[i]),
                };
            }
        }
        ParseError::GroupLength {
            group: 4,
            len: input.len() - BLOCK_STARTS[4],
        }
    }
}

impl FromStr for Uuid {
    type Err = ParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Uuid::parse_str(s)
    }
}

impl fmt::Display for Uuid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut buf = [0u8; 36];
        let mut pos = 0;
        for (i, byte) in self.0.iter().enumerate() {
            if matches!(i, 4 | 6 | 8 | 10) {
                buf[pos] = b'-';
                pos += 1;
            }
            buf[pos] = HEX_LOWER[(byte >> 4) as usize];
            buf[pos + 1] = HEX_LOWER[(byte & 0x0f) as usize];
            pos += 2;
        }
        // SAFETY-free: buffer only contains ASCII characters.
        f.write_str(std::str::from_utf8(&buf).expect("ascii"))
    }
}

impl fmt::Debug for Uuid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(self, f)
    }
}

impl Serialize for Uuid {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.collect_str(self)
    }
}

struct UuidVisitor;

impl<'de> Visitor<'de> for UuidVisitor {
    type Value = Uuid;

    fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("a UUID string")
    }

    fn visit_str<E: de::Error>(self, value: &str) -> Result<Uuid, E> {
        Uuid::parse_str(value)
            .map_err(|err| E::custom(format_args!("UUID parsing failed: {err}")))
    }

    fn visit_bytes<E: de::Error>(self, value: &[u8]) -> Result<Uuid, E> {
        match std::str::from_utf8(value) {
            Ok(s) => self.visit_str(s),
            Err(_) => Err(E::custom("UUID parsing failed: non-UTF8 input")),
        }
    }
}

impl<'de> Deserialize<'de> for Uuid {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Uuid, D::Error> {
        deserializer.deserialize_str(UuidVisitor)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip() {
        let id = Uuid::new_v4();
        let text = id.to_string();
        assert_eq!(text.len(), 36);
        assert_eq!(Uuid::parse_str(&text).unwrap(), id);
        assert_eq!(text.as_bytes()[14], b'4');
    }

    #[test]
    fn formats() {
        let id = Uuid::parse_str("11111111-2222-3333-4444-555555555555").unwrap();
        assert_eq!(Uuid::parse_str("11111111222233334444555555555555").unwrap(), id);
        assert_eq!(Uuid::parse_str("{11111111-2222-3333-4444-555555555555}").unwrap(), id);
        assert_eq!(
            Uuid::parse_str("urn:uuid:11111111-2222-3333-4444-555555555555").unwrap(),
            id
        );
        assert_eq!(
            Uuid::parse_str("11111111-2222-3333-4444-55555555555A").unwrap().to_string(),
            "11111111-2222-3333-4444-55555555555a"
        );
    }

    #[test]
    fn errors() {
        let e = |s: &str| Uuid::parse_str(s).unwrap_err().to_string();
        assert_eq!(e("not-a-uuid"), "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `n` at 1");
