/// Waits until the stream is readable (or has hit end-of-stream), returning
/// `false` if the deadline passes first.
fn wait_readable(stream: &TcpStream, deadline: Instant) -> io::Result<bool> {
    use std::os::unix::io::AsRawFd;

    loop {
        let now = Instant::now();
        if now >= deadline {
            return Ok(false);
        }
        let remaining = deadline - now;
        // Round up so that we never wake before the deadline.
        let millis = remaining
            .as_millis()
            .saturating_add(u128::from(remaining.subsec_nanos() % 1_000_000 != 0))
            .min(i32::MAX as u128) as i32;
        let mut pfd = libc::pollfd {
            fd: stream.as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        let ret = unsafe { libc::poll(&mut pfd, 1, millis) };
        if ret < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }
        if ret > 0 {
            return Ok(true);
        }
    }
